i2c_buses = {}
def i2c_bus(sda, scl, bloque):
    # Un bus por par de pines; los sensores que comparten SDA/SCL comparten el bus.
    clave = (sda, scl)
    if clave not in i2c_buses:
        try:
            if len(i2c_buses) < 2:
                i2c_buses[clave] = I2C(len(i2c_buses), scl=Pin(scl), sda=Pin(sda), freq=400000)
            else:
                i2c_buses[clave] = SoftI2C(scl=Pin(scl), sda=Pin(sda), freq=400000)
        except (ValueError, OSError) as error:
            rb_fail(bloque, "No se pudo iniciar I2C en SDA %s / SCL %s: %s" % (sda, scl, error))
    return i2c_buses[clave]
mpu_bus = None
mpu_direccion = 0x68
mpu_offset_z = 0
mpu_zona = 0.35
mpu_sentido = -1
mpu_acumulado = 0
mpu_ultimo = None
mpu_accel = [0, 0, 0]
mpu_velocidad = [0, 0, 0]
mpu_stage = 0
mpu_started = 0
mpu_calibrando = False
mpu_muestras = 0
mpu_validas = 0
mpu_suma_z = 0
mpu_muestra = 0

def mpu_millis():
    return time.ticks_ms() if hasattr(time, "ticks_ms") else int(time.monotonic() * 1000)

def mpu_elapsed(start):
    ahora = mpu_millis()
    return time.ticks_diff(ahora, start) if hasattr(time, "ticks_diff") else ahora - start

def mpu_ahora():
    return time.ticks_us() if hasattr(time, "ticks_us") else int(time.monotonic() * 1000000)

def mpu_crudos(bloque):
    if mpu_bus is None or mpu_stage != 3:
        rb_fail(bloque, "Configura la IMU MPU6050 al iniciar")
    try:
        datos = mpu_bus.readfrom_mem(mpu_direccion, 0x3B, 14)
        valores = []
        for i in range(0, 14, 2):
            v = datos[i] << 8 | datos[i+1]
            valores.append(v - 65536 if v > 32767 else v)
        return valores
    except OSError:
        rb_fail(bloque, "No responde MPU6050")

def mpu_actualizar(bloque):
    global mpu_ultimo, mpu_acumulado
    datos = mpu_crudos(bloque)
    ahora = mpu_ahora()
    elapsed = 0 if mpu_ultimo is None else (time.ticks_diff(ahora, mpu_ultimo) if hasattr(time, "ticks_diff") else ahora - mpu_ultimo)
    mpu_ultimo = ahora
    for i in range(3):
        mpu_accel[i] = datos[i] * (9.80665 / 16384)
        rate = datos[i+4] / 131 - (mpu_offset_z if i == 2 else 0)
        mpu_velocidad[i] = 0 if abs(rate) < mpu_zona else rate
    mpu_velocidad[2] *= mpu_sentido
    delta = mpu_velocidad[2] * elapsed / 1000000
    if not mpu_calibrando and math.isfinite(delta):
        mpu_acumulado += delta

def mpu_configurar(sda, scl, direccion, bloque):
    global mpu_bus, mpu_direccion, mpu_stage, mpu_offset_z, mpu_acumulado, mpu_ultimo, mpu_zona, mpu_sentido, mpu_calibrando
    mpu_bus = i2c_bus(sda, scl, bloque)
    mpu_direccion = int(direccion, 16)
    mpu_stage = 1
    mpu_offset_z = 0
    mpu_acumulado = 0
    mpu_ultimo = None
    mpu_zona = 0.35
    mpu_sentido = -1
    mpu_calibrando = False

def mpu_iniciar(bloque):
    global mpu_stage, mpu_started
    try:
        if mpu_stage == 1:
            if mpu_bus.readfrom_mem(mpu_direccion, 0x75, 1)[0] & 0x7E != 0x68:
                rb_fail(bloque, "No se encontro MPU6050 en la direccion elegida")
            mpu_bus.writeto_mem(mpu_direccion, 0x6B, bytes([0]))
            mpu_stage = 2
            mpu_started = mpu_millis()
            return False
        if mpu_stage == 2:
            if mpu_elapsed(mpu_started) < 100:
                return False
            for registro, valor in ((0x1A, 3), (0x1B, 0), (0x1C, 0)):
                mpu_bus.writeto_mem(mpu_direccion, registro, bytes([valor]))
            mpu_stage = 3
            mpu_actualizar(bloque)
        return True
    except OSError:
        rb_fail(bloque, "No responde MPU6050")

def mpu_calibrar(muestras, bloque):
    global mpu_calibrando, mpu_muestras, mpu_validas, mpu_suma_z, mpu_started, mpu_muestra
    if not math.isfinite(muestras) or muestras < 1 or muestras > 600 or int(muestras) != muestras:
        rb_fail(bloque, "Usa de 1 a 600 muestras enteras")
    mpu_actualizar(bloque)
    mpu_calibrando = True
    mpu_muestras = int(muestras)
    mpu_validas = 0
    mpu_suma_z = 0
    mpu_started = mpu_millis()
    mpu_muestra = mpu_started

def mpu_calibrar_paso(bloque):
    global mpu_validas, mpu_suma_z, mpu_muestra, mpu_offset_z, mpu_acumulado, mpu_ultimo, mpu_calibrando
    if mpu_elapsed(mpu_started) < 300 or mpu_elapsed(mpu_muestra) < 3:
        return False
    mpu_suma_z += mpu_crudos(bloque)[6]
    mpu_validas += 1
    mpu_muestra = mpu_millis()
    if mpu_validas < mpu_muestras:
        return False
    mpu_offset_z = mpu_suma_z / mpu_validas / 131
    mpu_acumulado = 0
    mpu_ultimo = mpu_ahora()
    mpu_calibrando = False
    return True

def mpu_reiniciar(bloque):
    global mpu_acumulado
    mpu_actualizar(bloque)
    mpu_acumulado = 0

def mpu_zona_muerta(zona, bloque):
    global mpu_zona
    if not math.isfinite(zona) or zona < 0 or zona > 250:
        rb_fail(bloque, "Zona muerta entre 0 y 250 grados/s")
    mpu_actualizar(bloque)
    mpu_zona = zona

def mpu_sentido_giro(sentido, bloque):
    global mpu_sentido
    mpu_actualizar(bloque)
    mpu_sentido = int(sentido)

def mpu_giro(bloque):
    mpu_actualizar(bloque)
    return round((mpu_acumulado + 180) % 360 - 180, 1)

def mpu_giro_acumulado(bloque):
    mpu_actualizar(bloque)
    return round(mpu_acumulado, 1)

def mpu_aceleracion(eje, bloque):
    mpu_actualizar(bloque)
    return mpu_accel["xyz".index(eje)]

def mpu_rapidez(eje, bloque):
    mpu_actualizar(bloque)
    return mpu_velocidad["xyz".index(eje)]

def mpu_inclinacion(eje, bloque):
    mpu_actualizar(bloque)
    x, y, z = mpu_accel
    return (math.atan2(-x, math.sqrt(y*y + z*z)) if eje == "2" else math.atan2(y, z)) * 180 / math.pi

inline bool rb_i2c_read(TwoWire& bus, uint8_t address, uint8_t reg, uint8_t* data, uint8_t count) {
    bus.beginTransmission(address); bus.write(reg);
    if (bus.endTransmission(false) != 0) return false;
    if (bus.requestFrom(address, count) != count) return false;
