inline bool mpu_crudos(int16_t* datos, const char* bloque) {
    uint8_t bytes[14];
    if (!mpu_bus || mpu_stage != 3) { rb_fail(bloque, "Configura la IMU MPU6050 al iniciar"); return false; }
    if (!rb_i2c_read(*mpu_bus, mpu_direccion, 0x3B, bytes, 14)) { rb_fail(bloque, "No responde MPU6050"); return false; }
    for (uint8_t i = 0; i < 7; i++) datos[i] = int16_t(uint16_t(bytes[2*i]) << 8 | bytes[2*i+1]);
