    float dt = mpu_tiene_tiempo ? uint32_t(ahora - mpu_ultimo) / 1000000.0f : 0;
    mpu_ultimo = ahora; mpu_tiene_tiempo = true;
    for (uint8_t i = 0; i < 3; i++) {
        mpu_accel[i] = datos[i] * (9.80665f / 16384.0f);
