def mpu_iniciar(bloque):
    global mpu_stage, mpu_started
    try:
        if mpu_stage == 1:
            if mpu_bus.readfrom_mem(mpu_direccion, 0x75, 1)[0] & 0x7E != 0x68:
                rb_fail(bloque, "No se encontro MPU6050 en la direccion elegida")
