inline bool rb_i2c_read(TwoWire& bus, uint8_t address, uint8_t reg, uint8_t* data, uint8_t count) {
    bus.beginTransmission(address); bus.write(reg);
    if (bus.endTransmission(false) != 0) return false;
    if (bus.requestFrom(address, count) != count) return false;
    for (uint8_t i = 0; i < count; i++) { int value = bus.read(); if (value < 0) return false; data[i] = value; } return true;
}
inline bool rb_i2c_write(TwoWire& bus, uint8_t address, uint8_t reg, uint8_t value) {
    bus.beginTransmission(address); bus.write(reg); bus.write(value); return bus.endTransmission() == 0;
}

