    ahora = mpu_millis()
    return time.ticks_diff(ahora, start) if hasattr(time, "ticks_diff") else ahora - start

def mpu_ahora():
    return time.ticks_us() if hasattr(time, "ticks_us") else int(time.monotonic() * 1000000)

